<script setup lang="ts">
import {ref,onMounted,onUnmounted,watch} from 'vue'
import {ArrowUpRight,Bookmark,Check,Clock3,Lightbulb,EyeOff,HelpCircle} from 'lucide-vue-next'
import {post,api,key,safeUrl} from '../api'
import type {Recommendation,State} from '../types'
import {useApp} from '../stores/app'
const props=defineProps<{item:Recommendation;index:number;batchId:string}>(),emit=defineEmits<{impression:[id:string]}>(),app=useApp(),element=ref<HTMLElement|null>(null),busy=ref(false),feedback=ref(false)
let observer:IntersectionObserver|undefined
function observe(){if(!app.profile?.onboarding_complete||!element.value)return;observer?.disconnect();observer=new IntersectionObserver(entries=>{if(entries.some(e=>e.isIntersecting)){emit('impression',props.item.topic.id);observer?.disconnect()}},{threshold:.35});observer.observe(element.value)}
onMounted(observe);watch(()=>app.profile?.onboarding_complete,observe)
onUnmounted(()=>observer?.disconnect())
async function bookmark(){if(busy.value)return;busy.value=true;try{const t=props.item.topic;if(t.state.bookmarked)await api(`/bookmarks/${t.id}`,{method:'DELETE'});else await post('/bookmarks',{topic_id:t.id});t.state.bookmarked=!t.state.bookmarked;app.notify(t.state.bookmarked?'已加入收藏':'已取消收藏')}catch(e){app.notify(e instanceof Error?e.message:'操作失败')}finally{busy.value=false}}
async function mark(action:string){busy.value=true;try{const result=await post<{state:State}>(`/topics/${props.item.topic.id}/feedback`,{action,idempotency_key:key()});props.item.topic.state=result.state;feedback.value=false;app.notify(action==='skip'?'已暂时跳过，不会永久屏蔽这个领域':'已保存你的自述反馈')}catch(e){app.notify(e instanceof Error?e.message:'反馈未保存')}finally{busy.value=false}}
</script>
<template><article ref="element" class="topic-card" :style="{'--discipline':item.topic.primary_discipline.color}"><div class="card-top"><span class="discipline-label"><i/>{{item.topic.primary_discipline.name}}<span v-if="item.topic.subfield" class="subfield"> / {{item.topic.subfield}}</span></span><span class="card-number">0{{index+1}}</span></div><div class="card-copy"><p v-if="item.topic.state.explored" class="visited-label"><Check :size="12"/>已探索</p><RouterLink :to="`/topics/${item.topic.id}`" class="topic-title"><h2>{{item.topic.title}}</h2><ArrowUpRight :size="23"/></RouterLink><p class="topic-question">{{item.topic.question||'这个概念，如何改变我们理解世界的方式？'}}</p><p class="topic-summary">{{item.topic.summary||item.topic.original_summary}}</p><div v-if="item.topic.value" class="topic-value"><Lightbulb :size="15"/><span>{{item.topic.value}}</span></div></div><div class="recommendation-reason"><span class="tiny-label">WHY THIS</span><p>{{item.reason}}</p></div><details v-if="item.bridge_path.length" class="bridge-path"><summary>查看 {{item.bridge_path.length}} 步跨领域路径</summary><div v-for="(hop,i) in item.bridge_path" :key="i"><RouterLink :to="`/topics/${hop.from_id}`">{{hop.from_title||hop.from_id}}</RouterLink><span> → {{hop.label}} → </span><RouterLink :to="`/topics/${hop.to_id}`">{{hop.to_id===item.topic.id?item.topic.title:hop.to_id}}</RouterLink><p>{{hop.explanation}}</p><a :href="safeUrl(hop.source_url)" target="_blank" rel="noopener noreferrer">关系依据 ↗</a></div></details><div class="card-meta"><span><Clock3 :size="13"/>约 {{item.topic.reading_minutes||1}} 分钟</span><a v-if="item.topic.sources[0]" :href="safeUrl(item.topic.sources[0].url)" target="_blank" rel="noopener noreferrer" :aria-label="`查看 ${item.topic.title} 的原始来源`">{{item.topic.sources[0].platform}}<ArrowUpRight :size="12"/></a><span v-else>来源暂不可用</span></div><div class="card-actions"><RouterLink :to="`/topics/${item.topic.id}`" class="explore-link">开始探索 <ArrowUpRight :size="16"/></RouterLink><div class="card-actions-right"><span v-if="item.topic.state.familiarity==='known'" class="mini-state">自述已了解</span><span v-if="item.topic.state.familiarity==='unfamiliar'" class="mini-state">自述陌生</span><button :class="['icon-button',{bookmarked:item.topic.state.bookmarked}]" :aria-label="item.topic.state.bookmarked?'取消收藏':'收藏主题'" :aria-pressed="item.topic.state.bookmarked" :disabled="busy" @click="bookmark"><Bookmark :size="17" :fill="item.topic.state.bookmarked?'currentColor':'none'"/></button><button class="icon-button" @click="feedback=!feedback" :aria-expanded="feedback" :aria-label="`${item.topic.title} 熟悉程度反馈`"><HelpCircle :size="17"/></button></div></div><div v-if="feedback" class="card-feedback"><span>此前你了解这个概念吗？</span><div><button :disabled="busy" @click="mark('known')"><Check :size="14"/>已了解</button><button :disabled="busy" @click="mark('unfamiliar')"><HelpCircle :size="14"/>完全陌生</button><button :disabled="busy" @click="mark('skip')"><EyeOff :size="14"/>暂时跳过</button></div></div></article></template>
